WL = "watchlist.csv"
shutil.copy(WL, WL + ".bak")                       # safety backup
rows = list(csv.reader(open(WL)))
header = rows[0]

# find ticker column, drop any existing 'sector' column
tcol = next((i for i,h in enumerate(header) if h.strip().lower()=="ticker"), 0)
if "sector" in [h.strip().lower() for h in header]:
    scol = [h.strip().lower() for h in header].index("sector")
    rows = [[c for j,c in enumerate(r) if j!=scol] for r in rows]
    header = rows[0]

out = [header + ["sector"]]
mapped = 0
for r in rows[1:]:
    if not r: continue
    tk = r[tcol].strip()
    sec = TICKER_SECTOR.get(tk, "")
    if sec: mapped += 1
    out.append(r + [sec])

csv.writer(open(WL,"w",newline="")).writerows(out)
print(f"Done. {mapped}/{len(out)-1} tickers mapped to a sector.")
print(f"Backup saved as {WL}.bak")
